template<class T>
[[nodiscard]] static constexpr T InvExpApprox(T X)
{
	constexpr T A(1.00746054f); // 1 / 1! in Taylor series
	constexpr T B(0.45053901f); // 1 / 2! in Taylor series
	constexpr T C(0.25724632f); // 1 / 3! in Taylor series
	return 1 / (1 + A * X + B * X * X + C * X * X * X);		
}

pub fn critical_spring_damper(
    current: f32,
    velocity: &mut f32,
    target: f32,
    delta_seconds: f32,
    half_life: f32,
) -> f32 {
    let smoothing_time = half_life / std::f32::consts::LN_2;
    if smoothing_time < 1e-8 {
        *velocity = 0.0;
        return target;
    }
    let y = 2.0 / smoothing_time.max(1e-8);
    let j0 = current - target;
    let j1 = *velocity + j0 * y;
    let e = inv_exp_approx(y * delta_seconds.max(0.0));
    let result = e * (j0 + j1 * delta_seconds.max(0.0)) + target;
    *velocity = e * (*velocity - j1 * y * delta_seconds.max(0.0));
    result
}

